mapper.select:
SELECT COUNT(*) > 0
FROM document_shares share
WHERE share.document_id = #{documentId}
  AND share.shared_with_user_id = #{userId}
  AND share.purpose = 'HEALTH_CERTIFICATE'

mapper.insert:
INSERT INTO document_access_logs (
    document_id, document_version_id, actor_user_id, action, result, denial_reason
) VALUES (
    #{documentId}, #{documentVersionId}, #{actorUserId},
    #{action}, #{result}, #{denialReason}
)
